from django.core.management.base import BaseCommand
from django.db import transaction
from library.models import Profile, Modifier, Control, ControlAction
from library.starter_actions import ACTIONS, REFERENCES

PROFILES = ['Software, SaaS, and application development', 'IT services and managed service providers', 'Online retail and e-commerce', 'Physical retail', 'Restaurants, cafés, and food service', 'Hotels, lodging, and hospitality', 'Healthcare practices and clinics', 'Dental and other outpatient specialty practices', 'Financial services and insurance', 'Legal services', 'Accounting, tax, and bookkeeping', 'Other professional and consulting services', 'Real estate and property management', 'Construction and skilled trades', 'Manufacturing', 'Transportation, logistics, and warehousing', 'Automotive repair and dealerships', 'Education and childcare', 'Nonprofits, associations, and religious organizations', 'Personal services, fitness, and recreation']
MODIFIERS = ['Payment processing', 'Sensitive health or financial data', 'Software development', 'Public applications', 'Remote workers', 'Operational technology', 'Multiple locations', 'Government contracts']
ROWS = [('GOV-01', 'Assign security ownership', 'Govern', 'Identify who accepts risk, approves changes, and coordinates incidents. Ask how decisions are reviewed.', 'Named owners, review schedule, and a recent decision record.', 'Unowned security decisions leave preventable gaps unresolved.', 'Assign accountable owners and schedule documented risk reviews.', 'Confirm owners can explain responsibilities and show a completed review.'), ('ID-01', 'Inventory assets and dependencies', 'Identify', 'Reconcile devices, cloud accounts, domains, critical applications, and providers with business owners.', 'Dated inventory, service owners, and critical dependency list.', 'Unknown assets and dependencies can remain exposed or interrupt operations.', 'Maintain an owned inventory and review changes and critical dependencies.', 'Sample devices and services against the inventory and resolve omissions.'), ('PR-01', 'Protect accounts and privileged access', 'Protect', 'Review administrative accounts, MFA coverage, recovery methods, and joiner/leaver practices. Do not collect credentials.', 'Redacted access lists, MFA coverage, and recent removal records.', 'Stolen or lingering access can expose data and interrupt business.', 'Require strong MFA where supported, minimize privileges, and promptly revoke departed-user access.', 'Sample privileged access and a recent departure; confirm access and recovery safeguards.'), ('PR-02', 'Manage updates and exposed services', 'Protect', 'Review patch ownership, unsupported software, internet-facing services, and how urgent vulnerabilities are handled.', 'Software versions, patch records, exposure inventory, and exception decisions.', 'Known vulnerabilities or unnecessary exposure can permit compromise.', 'Remove unnecessary exposure, replace unsupported software, and prioritize applicable urgent fixes.', 'Compare sampled versions and exposed services with the approved inventory and patch policy.'), ('PR-03', 'Protect business email', 'Protect', 'Inspect domain mail-authentication configuration, phishing reporting, and controls around payment-change requests.', 'DNS records, reporting procedure, and redacted payment-verification process.', 'Email impersonation can lead to fraud, stolen access, and lost customer trust.', 'Configure appropriate mail authentication, teach reporting, and verify sensitive changes through a trusted independent channel.', 'Review authentication results and walk through a sample suspicious payment request.'), ('PR-04', 'Secure business devices', 'Protect', 'Review device encryption, screen locks, endpoint safeguards, local administrator rights, and lost-device response.', 'Redacted device-policy and coverage reports.', 'Lost or compromised devices can expose business information.', 'Apply managed device safeguards and remove unnecessary administrator access.', 'Sample devices for policy compliance and walk through lost-device handling.'), ('PR-05', 'Know and protect sensitive data', 'Protect', 'Identify sensitive information, storage locations, sharing, retention obligations, and authorized access.', 'Data inventory, access review, retention policy, and redacted sharing settings.', 'Excess collection or access increases breach consequences and contractual exposure.', 'Minimize retained data, restrict access, and establish approved retention and deletion practices.', 'Sample access and sharing; confirm documented retention is applied.'), ('GOV-02', 'Review critical service providers', 'Govern', 'Identify critical vendors, shared responsibilities, account protections, outage dependencies, and exit options.', 'Vendor inventory, responsibility notes, contracts, and recovery dependencies.', 'Provider compromise or outage can affect the business even when IT is outsourced.', 'Assign vendor owners and document security responsibilities, recovery needs, and exit arrangements.', 'Review one critical provider against documented responsibilities and recovery needs.'), ('DE-01', 'Detect suspicious activity', 'Detect', 'Review relevant identity, endpoint, and service logs; determine who receives and investigates alerts.', 'Log-retention settings, alert routing, and redacted investigation examples.', 'Undetected compromise can persist and increase loss.', 'Retain appropriate logs and route actionable alerts to an accountable responder.', 'Generate a safe test event and verify it reaches the expected review process.'), ('RS-01', 'Prepare an incident response process', 'Respond', 'Walk through suspected account takeover, ransomware, and vendor breach scenarios with business owners.', 'Response contacts, escalation steps, communication plan, and exercise notes.', 'Uncoordinated response can prolong interruption and increase harm.', 'Document response roles, containment and escalation procedures, and exercise them.', 'Run a tabletop exercise and record corrective actions.'), ('RC-01', 'Back up and test recovery', 'Recover', 'Review backup coverage, separation from production access, restore history, and recovery objectives.', 'Backup reports, access boundaries, restore results, and business recovery targets.', 'Unrecoverable data or slow restoration can threaten operations.', 'Keep protected backups aligned to recovery needs and test restores regularly.', 'Restore a safe sample in isolation and compare measured recovery with business targets.'), ('SW-01', 'Review development tools and extensions', 'Protect', 'Inventory developer agents, extensions, installation hooks, repository permissions, and third-party code execution.', 'Approved tool list, permission review, dependency review, and change records.', 'Development tools or extensions can execute code and expose source or secrets.', 'Review tool provenance and permissions, restrict unapproved extensions, and isolate sensitive development access.', 'Inspect a representative development setup and verify installation and permission controls.'), ('PAY-01', 'Review payment responsibilities', 'Govern', 'Identify payment channels, provider responsibilities, merchant obligations, and payment-change processes.', 'Payment flow diagram, provider responsibility documentation, and scope review.', 'Payment compromise can cause fraud, interruption, and contractual consequences.', 'Minimize payment-data handling and confirm applicable responsibilities with the provider or qualified adviser.', 'Verify a representative payment flow and confirm ownership of each responsibility.'), ('OT-01', 'Separate operational systems', 'Protect', 'Identify operational equipment, remote vendor access, network boundaries, and safe maintenance constraints.', 'Equipment inventory, network diagram, remote-access approvals, and maintenance plans.', 'Compromised operational equipment can interrupt production or create safety consequences.', 'Restrict remote access and separate operational systems using a reviewed, safety-aware plan.', 'Review boundaries and access records without intrusive testing of live equipment.')]

class Command(BaseCommand):
    help = 'Load original starter drafts without overwriting existing controls or approving a baseline.'
    def add_arguments(self, parser):
        parser.add_argument('--enrich-existing', action='store_true', help='Add detailed guidance to unchanged original starter controls only; preserve custom guidance and existing actions.')

    @transaction.atomic
    def handle(self, *args, **options):
        for name in PROFILES: Profile.objects.get_or_create(name=name)
        for name in MODIFIERS: Modifier.objects.get_or_create(name=name)
        created_count = 0
        enriched_count = 0
        skipped = []
        for code,title,function,investigation,evidence,risk,recommendation,verification in ROWS:
            conditional = code in ['SW-01','PAY-01','OT-01']
            control,created = Control.objects.get_or_create(code=code,defaults=dict(title=title,function=function,universal=not conditional,applicability='All business profiles; validate scope during assessment.' if not conditional else {'SW-01':'Businesses developing software or using coding agents.','PAY-01':'Businesses accepting or handling payments.','OT-01':'Businesses operating connected production or operational equipment.'}[code],investigation=investigation,evidence=evidence,risk=risk,recommendation=recommendation,verification=verification,references='NIST CSF 2.0 function-level thematic reference (not a validated safeguard mapping): https://www.nist.gov/cyberframework\nOriginal draft guidance; detailed CIS/CISA/sector mappings require review.'))
            original_fields = dict(title=title, function=function, investigation=investigation, evidence=evidence, risk=risk, recommendation=recommendation, verification=verification)
            eligible = not control.actions.exists() and all(getattr(control, field) == value for field, value in original_fields.items())
            if created or (options['enrich_existing'] and eligible):
                if code == 'PR-01':
                    control.recommendation = 'Protect business accounts against phishing and unauthorized access, prioritizing privileged and business-critical accounts.'
                extra_reference = REFERENCES.get(code, '')
                if extra_reference and extra_reference not in control.references:
                    control.references += '\n' + extra_reference
                control.save()
                for position, (instruction, action_applicability, action_verification) in enumerate(ACTIONS[code], start=1):
                    ControlAction.objects.create(control=control, position=position, instruction=instruction, applicability=action_applicability, verification=action_verification)
                enriched_count += 1
            elif options['enrich_existing'] and not control.actions.exists():
                skipped.append(code)
            if created:
                created_count += 1
                if code == 'SW-01':
                    control.profiles.add(Profile.objects.get(name=PROFILES[0]),Profile.objects.get(name=PROFILES[1]))
                    control.modifiers.add(Modifier.objects.get(name='Software development'))
                if code == 'PAY-01':
                    control.profiles.add(*Profile.objects.filter(name__in=[PROFILES[i] for i in [2,3,4,5,16,19]]))
                    control.modifiers.add(Modifier.objects.get(name='Payment processing'))
                if code == 'OT-01':
                    control.profiles.add(Profile.objects.get(name=PROFILES[14]))
                    control.modifiers.add(Modifier.objects.get(name='Operational technology'))
        if skipped:
            self.stdout.write(self.style.WARNING('Preserved customized controls without actions: ' + ', '.join(skipped)))
        self.stdout.write(f'Added detailed actions to {enriched_count} controls.')
        self.stdout.write(self.style.SUCCESS(f'Created {created_count} draft controls; existing records preserved. No baseline approved.'))
